import ast, pathlib, inspect
p=pathlib.Path('examples/chat_console.py'); t=ast.parse(p.read_text())
for c in t.body:
 if isinstance(c,ast.ClassDef) and c.name in ('Streamer_basic','Streamer_rich'):
  f=next(n for n in c.body if isinstance(n,ast.FunctionDef) and n.name=='stream')
  sig=inspect.Signature([inspect.Parameter(a.arg,inspect.Parameter.POSITIONAL_OR_KEYWORD) for a in f.args.args])
  for label,args in [('parent',(None,'chunk','</think>')),('task',(None,'chunk','<think>','</think>'))]:
   try: sig.bind(*args); result='accepted'
   except TypeError as e: result='TypeError: '+str(e)
   print(c.name,label,str(sig),result)
